        "gu": "દશમ ભાવ પર શનિ અને ગુરુનું ગોચર લાંબા ગાળાની વ્યાવસાયિક જવાબદારીઓ પારખીને યોગ્ય ફળ આપે છે.",
        "bn": "দশম ঘরে শনি ও বৃহস্পতির গোচর দীর্ঘমেয়াদী পেশাগত দায়বদ্ধতার পরীক্ষা নিয়ে উপযুক্ত পুরস্কার প্রদান করে।",
        "ta": "பத்தாம் பாவகத்தின் மீது சனி மற்றும் குருவின் பெயர்ச்சி நீண்ட கால தொழில் பொறுப்புகளைச் சோதித்து நற்பலன்களைத் தரும்.",
        "te": "దశమ భావంపై శని, గురు గోచారాలు దీర్ఘకాలిక వృత్తిపరమైన బాధ్యతలను పరీక్షిస్తాయి మరియు సత్ఫలితాలను అందిస్తాయి.",
        "kn": "ದಶಮ ಭಾವದ ಮೇಲೆ ಶನಿ ಮತ್ತು ಗುರು ಗೋಚಾರವು ದೀರ್ಘಕಾಲೀನ ವೃತ್ತಿಪರ ಜವಾಬ್ದಾರಿಗಳನ್ನು ಪರೀಕ್ಷಿಸಿ ಫಲ ನೀಡುತ್ತದೆ.",
        "ml": "പത്താം ഭാവത്തിലൂടെയുള്ള ശനി, വ്യാഴ ഗോചാരങ്ങൾ ഉത്തരവാദിത്തങ്ങൾ പരീക്ഷിച്ച് ഉചിതമായ ഫലം നൽകും.",
