        "kn": "ವೃತ್ತಿಯ ಸಮಗ್ರ ಚಿತ್ರಣಕ್ಕಾಗಿ D10 (ದಶಾಂಶ) ಕುಂಡಲಿ ಮತ್ತು ಶನಿ, ಸೂರ್ಯರ ಬಲವನ್ನು ಕೂಲಂಕಷವಾಗಿ ಪರೀಕ್ಷಿಸಿ.",
