        "pa": "ਕਰੀਅਰ ਦੀ ਪੂਰੀ ਤਸਵੀਰ ਸਮਝਣ ਲਈ D10 ਕੁੰਡਲੀ ਅਤੇ ਸ਼ਨੀ ਤੇ ਸੂਰਜ ਦੇ ਬਲ ਦੀ ਜਾਂਚ ਕਰੋ।",
        "or": "କ୍ୟାରିୟରର ସମଗ୍ର ସ୍ଥିତି ବୁଝିବା ପାଇଁ D10 (ଦଶାଂଶ) କୁଣ୍ଡଳୀ ସହିତ ଶନି ଓ ସୂର୍ଯ୍ୟଙ୍କ ବଳ ଯାଞ୍ଚ କରନ୍ତୁ।",
