          "ta": "பத்தாம் அதிபதி D1 மற்றும் D10-ல் பலமாக இருந்து, ராகு ரிஷபம், மிதுனம், கன்னி அல்லது கும்பத்தில் அமைந்தால் மிகவும் சுபமாகும்.",
