        "te": "కేవలం భౌతిక ఆస్తులతో గుర్తింపును ఏర్పరచుకోకుండా, అంతరంగంలో శాశ్వత శాంతిని అన్వేషించే స్వభావం.",
        "kn": "ಭೌತಿಕ ಆಸ್ತಿಪಾಸ್ತಿಗಳಿಂದ ತನ್ನ ಗುರುತನ್ನು ರೂಪಿಸಿಕೊಳ್ಳದೆ, ಮನಸ್ಸಿನೊಳಗೆ ಶಾಶ್ವತ ಶಾಂತಿಯನ್ನು ಹುಡುಕುವ ಪ್ರವೃತ್ತಿ.",
        "ml": "ഭൗതിക സമ്പത്തിനേക്കാൾ മനസ്സിനുള്ളിൽ ശാശ്വതമായ ആത്മീയ ശാന്തി അന്വേഷിക്കുന്ന സ്വഭാവം.",
        "pa": "ਸਿਰਫ਼ ਦੌਲਤ ਨਾਲ ਆਪਣੀ ਪਛਾਣ ਨਾ ਬਣਾ ਕੇ ਮਨ ਅੰਦਰ ਅਟੱਲ ਆਤਮਿਕ ਸ਼ਾਂਤੀ ਲੱਭਣ ਦੀ ਰੁਚੀ।",
