        "ta": "நீர் ராசிகள் ஆன்மீக உணர்வை அதிகரிக்கின்றன; நில ராசிகள் குடும்ப பொறுப்புகளை சிறப்பாகக் கையாள உதவுகின்றன.",
        "te": "జల రాశులు ఆధ్యాత్మిక సున్నితత్వాన్ని పెంచుతాయి; భూ రాశులు గృహ బాధ్యతలను చక్కగా నిర్వహించడానికి తోడ్పడతాయి.",
        "kn": "ಜಲ ರಾಶಿಗಳು ಆಧ್ಯಾತ್ಮಿಕ ಸಂವೇದನೆಯನ್ನು ಹೆಚ್ಚಿಸುತ್ತವೆ; ಪೃಥ್ವಿ ರಾಶಿಗಳು ಕೌಟುಂಬಿಕ ಜವಾಬ್ದಾರಿಗಳನ್ನು ನಿಭಾಯಿಸಲು ನೆರವಾಗುತ್ತವೆ.",
        "ml": "ജലരാശികൾ ആത്മീയത വർദ്ധിപ്പിക്കുന്നു; ഭൂമിരാശികൾ കുടുംബ ഉത്തരവാദിത്തങ്ങൾ നിർവ്വഹിക്കാൻ സഹായിക്കുന്നു.",
        "pa": "ਜਲ ਰਾਸ਼ੀਆਂ ਰੂਹਾਨੀ ਸੰਵੇਦਨਸ਼ੀਲਤਾ ਵਧਾਉਂਦੀਆਂ ਹਨ; ਪ੍ਰਿਥਵੀ ਰਾਸ਼ੀਆਂ ਘਰੇਲੂ ਜ਼ਿੰਮੇਵਾਰੀਆਂ ਸੰਭਾਲਣ ਵਿੱਚ ਮਦਦ ਕਰਦੀਆਂ ਹਨ।",
